import{c as t,Q as n,j as e,m as i}from"./chunks/framework.BPKcPtvA.js";const k=JSON.parse('{"title":"Kelola Pelanggan PPPoE","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pppoe/pelanggan.md","filePath":"panduan/pppoe/pelanggan.md"}'),r={name:"panduan/pppoe/pelanggan.md"};function l(o,a,s,d,g,p){return n(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="kelola-pelanggan-pppoe" tabindex="-1">Kelola Pelanggan PPPoE <a class="header-anchor" href="#kelola-pelanggan-pppoe" aria-label="Permalink to &quot;Kelola Pelanggan PPPoE&quot;">​</a></h1><p>Halaman ini mencakup cara menambah, mengedit, dan mengelola pelanggan PPPoE secara individual maupun massal.</p><hr><h2 id="daftar-pelanggan" tabindex="-1">Daftar Pelanggan <a class="header-anchor" href="#daftar-pelanggan" aria-label="Permalink to &quot;Daftar Pelanggan&quot;">​</a></h2><p>Buka router → <strong>PPPoE → Pelanggan</strong> untuk melihat semua pelanggan.</p><p>Tabel menampilkan:</p><ul><li>Nama &amp; username pelanggan</li><li>Status koneksi (🟢 Online / 🔴 Offline)</li><li>Status akun (Aktif / Isolir / Suspended)</li><li>Profil layanan yang digunakan</li><li>Tombol aksi cepat</li></ul><p>Gunakan kolom <strong>pencarian</strong> di atas tabel untuk menyaring berdasarkan nama atau username.</p><hr><h2 id="menambah-pelanggan" tabindex="-1">Menambah Pelanggan <a class="header-anchor" href="#menambah-pelanggan" aria-label="Permalink to &quot;Menambah Pelanggan&quot;">​</a></h2><ol><li>Klik <strong>+ Tambah Pelanggan</strong></li><li>Isi form:</li></ol><h3 id="identitas" tabindex="-1">Identitas <a class="header-anchor" href="#identitas" aria-label="Permalink to &quot;Identitas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Nama Pelanggan</strong></td><td>Nama lengkap</td></tr><tr><td><strong>ID Pelanggan</strong></td><td>12 karakter huruf kapital &amp; angka, di-generate otomatis</td></tr><tr><td><strong>No. HP / WhatsApp</strong></td><td>Digunakan untuk notifikasi WA</td></tr><tr><td><strong>Email</strong></td><td>Digunakan untuk notifikasi email</td></tr><tr><td><strong>Alamat</strong></td><td>Alamat pemasangan</td></tr></tbody></table><h3 id="kredensial-pppoe" tabindex="-1">Kredensial PPPoE <a class="header-anchor" href="#kredensial-pppoe" aria-label="Permalink to &quot;Kredensial PPPoE&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Username</strong></td><td>Username PPPoE. Klik <strong>Generate Acak</strong> untuk 12 karakter unik, atau klik ikon <strong>=</strong> untuk menggunakan ID Pelanggan sebagai username</td></tr><tr><td><strong>Password</strong></td><td>Password PPPoE</td></tr><tr><td><strong>Profil Layanan</strong></td><td>Pilih dari profil yang sudah dibuat</td></tr></tbody></table><h3 id="lokasi" tabindex="-1">Lokasi <a class="header-anchor" href="#lokasi" aria-label="Permalink to &quot;Lokasi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Latitude</strong></td><td>Koordinat lintang lokasi pelanggan</td></tr><tr><td><strong>Longitude</strong></td><td>Koordinat bujur lokasi pelanggan</td></tr></tbody></table><p>Klik <strong>Pin di Peta</strong> untuk memilih lokasi secara visual dari peta interaktif.</p><h3 id="pengaturan-lanjutan" tabindex="-1">Pengaturan Lanjutan <a class="header-anchor" href="#pengaturan-lanjutan" aria-label="Permalink to &quot;Pengaturan Lanjutan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Port Modem</strong></td><td>Port fisik ODP/OLT untuk referensi teknisi</td></tr><tr><td><strong>Tanggal Pemasangan</strong></td><td>Tanggal instalasi</td></tr><tr><td><strong>Jatuh Tempo Override</strong></td><td>Ubah tanggal JT khusus untuk pelanggan ini (default mengikuti router)</td></tr><tr><td><strong>Auto Isolir</strong></td><td>Aktifkan agar pelanggan otomatis diisolir saat tagihan lewat jatuh tempo</td></tr></tbody></table><ol start="3"><li>Klik <strong>Simpan</strong> — pelanggan akan otomatis disync ke PPPoE Secret di MikroTik</li></ol><hr><h2 id="aksi-cepat-per-pelanggan" tabindex="-1">Aksi Cepat per Pelanggan <a class="header-anchor" href="#aksi-cepat-per-pelanggan" aria-label="Permalink to &quot;Aksi Cepat per Pelanggan&quot;">​</a></h2><p>Dari baris tabel, tersedia aksi:</p><table tabindex="0"><thead><tr><th>Aksi</th><th>Fungsi</th></tr></thead><tbody><tr><td><strong>Detail</strong></td><td>Buka halaman detail lengkap pelanggan</td></tr><tr><td><strong>Edit</strong></td><td>Edit data pelanggan</td></tr><tr><td><strong>Isolir</strong></td><td>Putuskan layanan pelanggan (walled garden redirect)</td></tr><tr><td><strong>Reconnect</strong></td><td>Aktifkan kembali pelanggan yang sedang diisolir</td></tr><tr><td><strong>Hapus</strong></td><td>Hapus pelanggan dari sistem dan MikroTik</td></tr></tbody></table><hr><h2 id="aksi-massal-bulk" tabindex="-1">Aksi Massal (Bulk) <a class="header-anchor" href="#aksi-massal-bulk" aria-label="Permalink to &quot;Aksi Massal (Bulk)&quot;">​</a></h2><p>Untuk mengelola banyak pelanggan sekaligus:</p><ol><li>Centang kotak di sebelah kiri nama pelanggan</li><li>Centang kotak di header tabel untuk memilih semua pelanggan di halaman ini</li><li>Bar aksi massal akan muncul di bagian bawah layar</li></ol><p>Aksi yang tersedia:</p><table tabindex="0"><thead><tr><th>Aksi</th><th>Fungsi</th></tr></thead><tbody><tr><td><strong>Isolir</strong></td><td>Isolir semua pelanggan yang dipilih</td></tr><tr><td><strong>Suspend</strong></td><td>Suspend akun pelanggan yang dipilih</td></tr><tr><td><strong>Hapus</strong></td><td>Hapus permanen semua pelanggan yang dipilih</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Aksi massal <strong>Hapus</strong> tidak dapat dibatalkan. Semua data pelanggan termasuk riwayat tagihan akan terhapus permanen.</p></div><hr><h2 id="halaman-detail-pelanggan" tabindex="-1">Halaman Detail Pelanggan <a class="header-anchor" href="#halaman-detail-pelanggan" aria-label="Permalink to &quot;Halaman Detail Pelanggan&quot;">​</a></h2><p>Klik nama pelanggan atau tombol <strong>Detail</strong> untuk membuka halaman detail yang berisi:</p><h3 id="tab-tagihan" tabindex="-1">Tab Tagihan <a class="header-anchor" href="#tab-tagihan" aria-label="Permalink to &quot;Tab Tagihan&quot;">​</a></h3><p>Riwayat semua tagihan bulanan beserta status (Lunas / Belum Bayar / Terlambat).</p><h3 id="tab-pembayaran" tabindex="-1">Tab Pembayaran <a class="header-anchor" href="#tab-pembayaran" aria-label="Permalink to &quot;Tab Pembayaran&quot;">​</a></h3><p>Riwayat semua transaksi pembayaran yang sudah dikonfirmasi.</p><h3 id="tab-kredensial" tabindex="-1">Tab Kredensial <a class="header-anchor" href="#tab-kredensial" aria-label="Permalink to &quot;Tab Kredensial&quot;">​</a></h3><p>Username, password, profil layanan, IP PPPoE, uptime sesi, dan status sinkronisasi ke MikroTik.</p><h3 id="tab-live-traffic" tabindex="-1">Tab Live Traffic <a class="header-anchor" href="#tab-live-traffic" aria-label="Permalink to &quot;Tab Live Traffic&quot;">​</a></h3><p>Grafik kecepatan upload/download real-time (diperbarui setiap 5 detik). Memerlukan koneksi VPN router aktif.</p><h3 id="tab-lokasi" tabindex="-1">Tab Lokasi <a class="header-anchor" href="#tab-lokasi" aria-label="Permalink to &quot;Tab Lokasi&quot;">​</a></h3><p>Peta interaktif menampilkan lokasi pelanggan berdasarkan koordinat yang tersimpan. Tersedia tombol <strong>Buka di Google Maps</strong> untuk navigasi langsung.</p><h3 id="tab-lampiran" tabindex="-1">Tab Lampiran <a class="header-anchor" href="#tab-lampiran" aria-label="Permalink to &quot;Tab Lampiran&quot;">​</a></h3><p>Upload dan kelola dokumen terkait pelanggan (foto instalasi, KTP, dll).</p><h3 id="tab-notifikasi" tabindex="-1">Tab Notifikasi <a class="header-anchor" href="#tab-notifikasi" aria-label="Permalink to &quot;Tab Notifikasi&quot;">​</a></h3><p>Riwayat semua notifikasi WA/Email yang pernah dikirim ke pelanggan.</p>',49)])])}const u=t(r,[["render",l]]);export{k as __pageData,u as default};
